// Statuses that represent an outreach attempt (message/call sent). The legacy per-channel
// statuses (sms/whatsapp/facebook_msg/contacted/sent_*) were removed from the vocabulary —
// initial_contact is the unified live equivalent, so the usage-metering + team-claim hooks
// below fire on a manual move into it.
const OUTREACH_STATUSES: LeadStatus[] = ['initial_contact'];

interface OutreachHistoryEntry {
  business_name: string;
  google_maps_url: string | null;
   phone: string | null;
  country?: string | null;
}

export type PhoneFetchStatus = 'pending' | 'success' | 'no_phone' | 'failed';

/* ════════════════════════════════════════════════════════════════════════════════════════════════
   WHAT THE LEAD-CREATION ENRICHMENT WRITES, and why this is one function used by three call sites.

   THE BUG. `google-place-details` used to ask Google for phone + website only, on the strength of a
   comment saying Text Search already returned the address. It hadn't for a long time (search-leads'
   field mask is id/displayName/googleMapsUri/websiteUri), so `address` was null on every
   search-added lead — and with no address there were no addressComponents, hence no derived_town.
   The audit location chain is confirmed_location || derived_town || search_location, so a lead could
   reach the audit button with nothing at all to say where the business is.

   The call now returns address, rating, review count and the derived town as well, at NO extra cost
   (phone is an Enterprise-tier field, so the request was already billed at the tier that contains
   rating and userRatingCount — see _shared/place-details.ts for Google's rule, quoted).

   THREE CALL SITES used to each hand-roll their own update, and two of them only wrote anything at
   all when a phone came back — so a business Google has no phone for would silently lose the address
   and rating we had just paid for. One function now, so that cannot drift again.
   ════════════════════════════════════════════════════════════════════════════════════════════════ */

interface PlaceDetailsResponse {
  phone?: string | null;
  website?: string | null;
  address?: string | null;
  category?: string | null;
  rating?: number | null;
  reviewCount?: number | null;
  derivedTown?: string | null;
  /** null = a town was found. Absent entirely = the edge function predates this change. */
  townNote?: string | null;
}

/** 🔴 COVERAGE: ADDED TO CRM (2026-09-29). Called only AFTER an insert succeeded, for a result that
 *  came from a recorded search run: credits the business to that run, with the search's own website
 *  verdict. Fire-and-forget — reporting must never slow or fail an add. */
function recordSearchAddition(lead: Lead) {
  const runId = lead.searchRunId;
  const key = businessKey(lead);
  if (!runId || !key) return;
  void Promise.resolve((supabase.rpc as unknown as (n: string, a: unknown) => Promise<{ error: unknown }>)('record_search_addition', {
    _run_id: runId, _key: key, _without_website: isWithoutWebsite(lead.websiteStatus),
  })).catch(() => {});
}

/** One Place Details lookup for a salesperson's add (see addLead). null on any failure — the add goes
 *  ahead with what the search returned. */
async function lookupPlaceDetails(placeId: string): Promise<(PlaceDetailsResponse & { email?: string | null }) | null> {
  try {
    const { data, error } = await supabase.functions.invoke('google-place-details', {
      body: { placeId, triggerSource: 'add_to_crm' },
    });
    if (error || !data || typeof data !== 'object') return null;
    const d = data as PlaceDetailsResponse & { error?: string; email?: string | null };
    // The function answers a failed Google call with 200 + { error, phone: null }: that is not an answer.
    if (d.error) return null;
    return d;
  } catch {
    return null;
  }
}

/** Columns added by SQL Paul applies BY HAND. PostgREST rejects the WHOLE update for one unknown
 *  column, so the write is attempted in full and retried without these. Losing the rating must never
 *  cost us the phone number — the same trap that produced the migration-tolerance fix in 3b93284d. */
const HAND_MIGRATED_LEAD_COLS = ['rating', 'review_count', 'derived_town', 'town_fetched_at', 'town_fetch_note'] as const;

/**
 * Write everything a Place Details lookup returned onto the lead. Returns the updated row, or null
 * if there was nothing to write or the write failed.
 *
 * Only fields that actually came back are written, so a legacy cache row (which carries no address
 * or rating) can never blank a value we already hold. The town block is the exception: a null
 * derived_town IS written, together with the note explaining why, because "ran and found nothing"
 * has to be distinguishable from "never ran" — that distinction is the only reason this bug was
 * findable at all.
 */
async function applyPlaceDetailsToLead(
  leadId: string,
  details: PlaceDetailsResponse,
): Promise<OutreachLead | null> {
  const updates: Record<string, unknown> = {};
  if (details.phone != null) updates.phone = details.phone;
  if (details.website != null) updates.website = details.website;
  if (details.address != null) updates.address = details.address;
  /* ⛔ THE COUNTRY THE ADDRESS NAMES (2026-09-28, leadCountry.ts) — the lead's country was the search
     form's hidden choice, and 349 UK businesses were stored as USA that way. Only a recognised
     trailing country is written; anything else leaves the stored value alone. */
  const addressCountry = countryFromAddress(details.address);
  if (addressCountry) updates.country = addressCountry;
  if (details.category != null) updates.category = details.category;
  if (details.rating != null) updates.rating = details.rating;
  if (details.reviewCount != null) updates.review_count = details.reviewCount;

  /* Stamp the town ONLY when the server actually reported on it. `townNote === undefined` means the
     edge function has not been redeployed yet, and stamping town_fetched_at from an old response
     would claim the fetch ran when it never asked for an address — poisoning the 30-day cache in
     place-town.ts with a permanent "we looked, there's nothing there". */
  if (details.townNote !== undefined) {
    updates.derived_town = details.derivedTown ?? null;
    updates.town_fetched_at = new Date().toISOString();
    updates.town_fetch_note = details.townNote;
  }

  if (Object.keys(updates).length === 0) return null;

  const { data, error } = await supabase
    .from('outreach_leads')
    .update(updates as never)
    .eq('id', leadId)
    .select()
    .single();

  if (!error) return data as OutreachLead;

  /* Retry without the hand-migrated columns. Detected by name in the error rather than by probing the
     schema, matching how audit-baseline.ts and AiAudit.tsx handle the same situation.

     QUOTED name + a schema-shaped message, deliberately. A bare substring test for 'rating' is the
     trap CLAUDE.md §4 keeps catching us on — the same class of bug as "bing" matching plumbing. The
     PostgREST message is: Could not find the 'rating' column of 'outreach_leads' in the schema cache.
     Requiring the quotes AND the column/schema wording means an unrelated failure that happens to
     contain the word cannot silently drop five columns and report success. */
  const msg = error.message ?? '';
  const looksLikeMissingColumn = /column|schema cache/i.test(msg);
  const missing = looksLikeMissingColumn
    ? HAND_MIGRATED_LEAD_COLS.filter((c) => msg.includes(`'${c}'`) || msg.includes(`"${c}"`))
    : [];
  if (missing.length === 0) {
    console.error('Place details write failed:', msg);
    return null;
  }
  console.warn(`Place details write: columns not present yet (${missing.join(', ')}) — retrying without them. Run the SQL to store these.`);
  for (const c of HAND_MIGRATED_LEAD_COLS) delete updates[c];
  if (Object.keys(updates).length === 0) return null;
  const retry = await supabase
    .from('outreach_leads')
    .update(updates as never)
    .eq('id', leadId)
    .select()
    .single();
  if (retry.error) {
    console.error('Place details write failed on retry:', retry.error.message);
    return null;
  }
  return retry.data as OutreachLead;
}

/* ⚡ `history: false` (2026-09-27, site-wide speed pass): the Outreach page and the Inbox's lead
   dialog never call addLead or isInOutreach — the only two readers of outreach_history — yet every
   mount downloaded all ~5,400 rows of it (7 requests, 1.2 MB). They opt out. A mount that opts out
   must not call either (scripts/outreach-list-columns.test.ts checks the two that do). */
/* ⚡ `progressive: true` — the Outreach page only (2026-09-28, src/lib/outreachLoad.ts). The first load
   shows the newest OUTREACH_FIRST_BATCH leads as soon as they arrive and loads the rest behind them;
   `leadLoad` says how complete the list is, and everything that needs the whole dataset gates on
   datasetComplete(leadLoad). Every other caller loads the whole list first, exactly as before. */
/* ⚡ `preload: false` — Find Leads only (2026-10-13, src/lib/findLeadsCrmMatch.ts). Find Leads needs addLead and
   removeFreshLead, never the list: it marks its results with a lookup for the results on screen. Nothing is
   downloaded on mount and fetchLeads does nothing, so the whole book (~5,600 leads + archive + history, ~17
   requests) is never read there. addLead's database dedupe is unchanged, and the outreach_history pre-check it
   can no longer do in memory is asked of the database for that one business. */
/* ⚡ `onlyLeadId` — the Inbox's lead dialog only (2026-10-15). It shows ONE lead, yet loaded the whole book
   (~5,800 active leads + the archive, ~8 requests, several MB) every time a lead was opened from the Inbox. With
   onlyLeadId the list is that one ACTIVE lead (same source, same list columns, same `is_archived = false` the full
   load uses — so an archived lead still reads as "not found"), and the archive stays empty. The writers are
   unchanged: they patch the row in the list exactly as before. Never pass it from a screen that shows the list. */
export function useOutreach({ history = true, progressive = false, preload = true, onlyLeadId }: { history?: boolean; progressive?: boolean; preload?: boolean; onlyLeadId?: string } = {}) {
  const [leads, setLeads] = useState<OutreachLead[]>([]);
  const [archivedLeads, setArchivedLeads] = useState<OutreachLead[]>([]);
  const [leadLoad, setLeadLoad] = useState<LeadLoadState>(LEAD_LOAD_INITIAL);
  const leadLoadRef = useRef<LeadLoadState>(LEAD_LOAD_INITIAL);
  leadLoadRef.current = leadLoad;
  /* The rows as they are NOW (for the merge when the background load lands), the rows first put on
     screen (identity = "not edited since"), and a generation so a superseded load never lands. */
  const latestRef = useRef<{ active: OutreachLead[]; archived: OutreachLead[] }>({ active: [], archived: [] });
  latestRef.current = { active: leads, archived: archivedLeads };
  const shownRef = useRef<{ active: OutreachLead[]; archived: OutreachLead[]; first: OutreachLead[]; total: number | null } | null>(null);
  const loadGenRef = useRef(0);
  const [activities, setActivities] = useState<OutreachActivity[]>([]);
  const [outreachHistory, setOutreachHistory] = useState<OutreachHistoryEntry[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const hasLoadedOnceRef = useRef(false);
  const [phoneFetchStatus, setPhoneFetchStatus] = useState<Record<string, PhoneFetchStatus>>({});
  const { toast } = useToast();
  const { user } = useAuth();
  /* The role is read through a ref so addLead (deps [user]) always sees the current one. */
  const { role } = useSubscription();
  const roleRef = useRef(role);
  roleRef.current = role;
  /* This instance's name on the lead-changed signal: it already holds the row it just wrote, so it
     skips its own notice while every OTHER reader (the Inbox, another Outreach, the CRM panel) re-reads. */
  const syncOriginRef = useRef(`outreach-${Math.random().toString(36).slice(2)}`);
  // Stable user ID ref to prevent refetches on auth token refreshes
  const userIdRef = useRef<string | null>(null);

  /* ══ A SALESPERSON ON THE SAME OUTREACH (2026-09-27) ════════════════════════════════════════════
     One hook, one page, both roles. What differs is WHERE the rows come from and HOW a change is
     written — never what the screen is:
       · reads: the admin reads outreach_leads; a salesperson reads the safe sales_leads view
         (leadSourceFor) — only their assigned prospects, no money/delivery/admin-note columns;
       · writes: a salesperson has NO direct write on outreach_leads (RLS makes it a silent no-op),
         so every change goes through salesPatchLead → the ownership-checked lead functions, and the
         row is then re-read from the view. A change they may not make is refused out loud.
     The admin's paths below are unchanged: every sales branch returns before them. */
  const isSales = () => roleRef.current === 'sales';
  const refuseForSales = useCallback((what: string) => {
    toast({ title: 'Admin only', description: `${what} is done by the admin.`, variant: 'destructive' });
  }, []);
  /** Put one freshly-read row in the right list (active / archived). */
  const placeRow = useCallback((row: OutreachLead) => {
    const put = (prev: OutreachLead[]) => (prev.some((l) => l.id === row.id) ? prev.map((l) => (l.id === row.id ? row : l)) : [row, ...prev]);
    setLeads((prev) => (row.is_archived ? prev.filter((l) => l.id !== row.id) : put(prev)));
    setArchivedLeads((prev) => (row.is_archived ? put(prev) : prev.filter((l) => l.id !== row.id)));
  }, []);
  const salesUpdateLead = useCallback(async (leadId: string, updates: Record<string, unknown>): Promise<OutreachLead | null> => {
    const r = await salesPatchLead(leadId, updates);
    if (!r.ok) {
      toast({ title: 'Not saved', description: refusalText(r.error), variant: 'destructive' });
      return null;
    }
    if (!r.wrote) return null; // nothing a salesperson stores (e.g. the contact-method tag)
    const src = leadSourceFor('sales');
    const { data, error } = await (supabase as unknown as { from: (t: string) => any })
      .from(src.table).select(src.listSelect).eq('id', leadId).maybeSingle();
    if (error || !data) return null;
    const row = data as OutreachLead;
    /* A not-interested lead is protected from further contact exactly as the admin's is. */
    if (updates.status === 'not_interested') {
      void supabase.functions.invoke('process-whatsapp-queue', { body: { mode: 'suppress_lead', lead_id: leadId, reason: 'not_interested' } })
        .then(({ data: sd, error: se }) => {
          if (se || (sd as { ok?: boolean } | null)?.ok !== true) {
            console.error(`[useOutreach] suppression write FAILED for lead ${leadId} (not_interested)`, se ?? sd);
            toast({ title: 'Status saved, but contact block failed', description: 'The lead is marked, but nothing is stopping future outreach to this number yet. Try again.', variant: 'destructive' });
          }
        });
    }
    placeRow(row);
    notifyLeadChanged(leadId, syncOriginRef.current);
    return row;
  }, []);
  /* A change made OUTSIDE this hook's own writers — the CRM panel's functions, a salesperson's queue
     — announces itself as 'lead-row-changed'; the row is re-read here (from the caller's own source,
     so a salesperson reads the view) and replaces the stale copy. Only a row already in the lists. */
  useEffect(() => {
    const onChanged = async (e: Event) => {
      const detail = (e as CustomEvent<{ leadId?: string; origin?: string; patch?: Record<string, unknown>; optimistic?: boolean }>).detail;
      const leadId = detail?.leadId;
      if (!leadId || detail?.origin === syncOriginRef.current) return;
      if (detail?.patch) {
        const p = detail.patch as Partial<OutreachLead>;
        setLeads((prev) => prev.map((l) => (l.id === leadId ? { ...l, ...p } : l)));
        setArchivedLeads((prev) => prev.map((l) => (l.id === leadId ? { ...l, ...p } : l)));
      }
      if (detail?.optimistic) return; // the server has not answered; a re-read now would bring back the old row
      const src = leadSourceFor(roleRef.current);
      const { data, error } = await (supabase as unknown as { from: (t: string) => any })
        .from(src.table).select(src.listSelect).eq('id', leadId).maybeSingle();
      if (error) return;
      /* A salesperson's view answering NO ROW means the lead is no longer theirs (removed from their
         leads, or reassigned by the admin): drop the stale copy rather than keep showing it. */
      if (!data) {
        if (roleRef.current === 'sales') {
          setLeads((prev) => prev.filter((l) => l.id !== leadId));
          setArchivedLeads((prev) => prev.filter((l) => l.id !== leadId));
        }
        return;
      }
      placeRow(data as OutreachLead);
    };
    window.addEventListener('lead-row-changed', onChanged);
    return () => window.removeEventListener('lead-row-changed', onChanged);
  }, [placeRow]);

  /* ══ KEEP THE COVERAGE COUNTS HONEST ══════════════════════════════════════════════════════════
     ⛔ THE BUG: Coverage's "12 leads" badge and its summary come from the `coverage` edge function,
     cached by React Query at staleTime 5 minutes with refetchOnWindowFocus OFF. NOTHING invalidated
     it on a write — so adding a lead on Find Leads and going back to Coverage inside five minutes
     served the PRE-ADD payload, and only a hard refresh (which discards the in-memory cache) showed
     the truth. It was never a re-render problem: the component re-rendered correctly, over stale data.

     ⛔ IT HAS TO BE INVALIDATED BY THE WRITER, NOT BY A LISTENER IN useCoverage. Coverage is
     UNMOUNTED when a lead is added — that page has no add button — so nothing there is listening.
     invalidateQueries works with no subscriber: it marks the cache stale so the NEXT mount refetches.

     ⛔ AND THE TRIGGER IS DERIVED, NOT SPRINKLED. Nine functions in this hook change what that
     endpoint counts (add, delete, removeFresh, archiveInternal, archiveAll, archiveMultiple,
     unarchive, unarchiveMultiple, the inline auto-archive). Nine remembered calls is a rule the
     tenth writer breaks — the shape this codebase keeps getting caught by. Watching the lead state
     the SCREEN renders makes "the list changed" and "coverage is stale" one event, and a future
     write cannot forget to announce itself.

     ⚠️ NO OPTIMISTIC NUMBER, EVER. This invalidates and lets the server answer; it never adds 1 to a
     count locally. An invented figure would drift from the CRM the moment a dedupe silently skipped
     an add — and the whole value of that badge is that it is real. */
  const queryClient = useQueryClient();
  const coverageSig = useMemo(() => coverageSignature(leads, archivedLeads), [leads, archivedLeads]);
  /* Skips the FIRST value, which is the initial load (0 leads → N) rather than an operator action.
     Invalidating there would refetch coverage once per Outreach visit for no change. */
  /* ⚡ (2026-09-28) Watching starts when the list is COMPLETE: the empty mount value and every step of
     a load (the first 1,000, then the rest) are loading, not an operator action — before, the load
     itself invalidated coverage once per visit. */
  const seenFirstSig = useRef(false);
  const listComplete = datasetComplete(leadLoad);
  useEffect(() => {
    if (!listComplete) return;
    if (!seenFirstSig.current) { seenFirstSig.current = true; return; }
    void queryClient.invalidateQueries({ queryKey: coverageQueryKey(user?.id) });
  }, [coverageSig, queryClient, user?.id, listComplete]);

  // Parallel phone fetch queue — processes up to 3 leads concurrently for speed.
  // `email` (if the lead already has one) rides along so a no-phone lead is only
  // dropped when it ALSO has no email — email-only leads are workable.
  const phoneQueueRef = useRef<Array<{ outreachLeadId: string; placeId: string; businessName: string; email?: string | null }>>([]);
  const isProcessingQueueRef = useRef(false);
  const queuedPlaceIdsRef = useRef<Set<string>>(new Set()); // Dedup: prevent same place_id being queued twice per session
  const CONCURRENCY = 3;
  // Names of leads dropped for having NO phone AND no email, collected across one
  // queue drain so a bulk add surfaces ONE "N skipped — no contact method" toast
  // instead of one per lead.
  const removedNoPhoneRef = useRef<string[]>([]);

  const removeLeadNoPhone = useCallback(async (outreachLeadId: string, businessName: string) => {
    // Delete the lead from the database
    await supabase.from('outreach_leads').delete().eq('id', outreachLeadId);
    // Remove from local state
    setLeads(prev => prev.filter(l => l.id !== outreachLeadId));
    setArchivedLeads(prev => prev.filter(l => l.id !== outreachLeadId));
    // Clean up outreach_history so business can be re-added later
    await supabase.from('outreach_history').delete().eq('business_name', businessName);
    setOutreachHistory(prev => prev.filter(h => h.business_name !== businessName));
    // Collect the name — the aggregated toast fires once, when the queue drains,
    // so a bulk add doesn't spray one toast per no-phone lead.
    removedNoPhoneRef.current.push(businessName);
    // Notify walkthrough to decrement CRM add count
    window.dispatchEvent(new CustomEvent('crm-lead-purged'));
  }, []);

  const fetchOnePhone = useCallback(async (item: { outreachLeadId: string; placeId: string; businessName: string; email?: string | null }) => {
    setPhoneFetchStatus(prev => ({ ...prev, [item.outreachLeadId]: 'pending' }));
    try {
      const { data: details, error: detailsError } = await supabase.functions.invoke('google-place-details', {
        body: { placeId: item.placeId, triggerSource: 'add_to_crm' },
      });

      if (detailsError || !details) {
        console.log('Phone enrichment returned no data for', item.businessName);
        // Keep the lead in the CRM. User can manually retry.
        setPhoneFetchStatus(prev => ({ ...prev, [item.outreachLeadId]: 'failed' }));
        return;
      }

      /* WRITE FIRST, decide about the phone SECOND. This used to be the other way round: the no-phone
         branch below returned early, so the address, town and rating we had just paid Google for were
         thrown away for any business with no listed phone number. The lookup is one call covering all
         of it — whatever came back gets stored. */
      const updated = await applyPlaceDetailsToLead(item.outreachLeadId, details as PlaceDetailsResponse);
      if (updated) {
        setLeads(prev => prev.map(l => l.id === item.outreachLeadId ? updated : l));
      }

      if (!details.phone) {
        // Enrichment succeeded but Google has no phone for this business. Keep the
        // lead if it still has an email (email-only outreach is workable); drop it
        // ONLY when it has NEITHER phone nor email — a dead row with no contact
        // method. Email may already be on the lead (carried enrichment, threaded via
        // item.email) or come back from the lookup. removeLeadNoPhone collects the
        // name for the aggregated "N skipped — no contact method" toast on drain.
        setPhoneFetchStatus(prev => ({ ...prev, [item.outreachLeadId]: 'no_phone' }));
        const email = String(details.email ?? item.email ?? '').trim();
        if (!email) {
          await removeLeadNoPhone(item.outreachLeadId, item.businessName);
        }
        return;
      }

      setPhoneFetchStatus(prev => ({ ...prev, [item.outreachLeadId]: 'success' }));
    } catch (e) {
      console.error('Phone enrichment failed (non-blocking):', e);
      setPhoneFetchStatus(prev => ({ ...prev, [item.outreachLeadId]: 'failed' }));
    }
  }, [removeLeadNoPhone]);

  const processPhoneQueue = useCallback(async () => {
    if (isProcessingQueueRef.current) return;
    isProcessingQueueRef.current = true;

    while (phoneQueueRef.current.length > 0) {
      const batch = phoneQueueRef.current.splice(0, CONCURRENCY);
      await Promise.all(batch.map(fetchOnePhone));
    }

    isProcessingQueueRef.current = false;

    // Queue drained — fire ONE toast for everything dropped this pass (no phone AND
    // no email). Leads kept because they had an email are NOT counted or named here.
    const dropped = removedNoPhoneRef.current;
    if (dropped.length > 0) {
      removedNoPhoneRef.current = [];
      toast({
        title: dropped.length === 1 ? dropped[0] : `${dropped.length} skipped — no contact method`,
        description: dropped.length === 1
          ? 'No phone or email found — not added.'
          : `No phone or email found — not added: ${dropped.join(', ')}.`,
        variant: 'destructive',
      });
    }
  }, [fetchOnePhone, toast]);

  const enqueuePhoneFetch = useCallback((outreachLeadId: string, placeId: string, businessName: string, email?: string | null) => {
    // Dedup: skip if this place_id has already been queued this session
    if (queuedPlaceIdsRef.current.has(placeId)) {
      console.log(`Skipping duplicate phone fetch for place_id ${placeId} (${businessName})`);
      return;
    }
    queuedPlaceIdsRef.current.add(placeId);
    setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'pending' }));
    phoneQueueRef.current.push({ outreachLeadId, placeId, businessName, email });
    processPhoneQueue();
  }, [processPhoneQueue]);

  /* ── THE BACKGROUND HALF: every page after the first, then the merge. ───────────────────────── */
  const loadRemainingLeads = useCallback(async (gen: number) => {
    const shown = shownRef.current;
    if (!shown) return;
    const src = leadSourceFor(roleRef.current);
    const buildActive = (from: number, to: number) => (supabase as unknown as { from: (t: string) => any })
      .from(src.table).select(src.listSelect).eq('is_archived', false)
      .order('created_at', { ascending: false }).order('id', { ascending: true }).range(from, to);
    try {
      const all = await fetchPagesAfterFirst<OutreachLead>(buildActive, (l) => l.id, shown.first, shown.total);
      if (gen !== loadGenRef.current) return;
      // Page 0's rows come back as the very objects already on screen; only the new ones are guarded.
      const fetchedActive = [...all.slice(0, shown.first.length), ...guardListRows(all.slice(shown.first.length), 'useOutreach')];
      const merged = mergeAfterBackgroundLoad({
        shownActive: shown.active, shownArchived: shown.archived,
        localActive: latestRef.current.active, localArchived: latestRef.current.archived,
        fetchedActive, fetchedArchived: shown.archived,
      });
      setLeads(merged.active);
      setArchivedLeads(merged.archived);
      setLeadLoad(LEAD_LOAD_COMPLETE(merged.active.length));
    } catch (e) {
      if (gen !== loadGenRef.current) return;
      const message = errorMessageOf(e);
      console.error('Outreach: the remaining leads failed to load:', e);
      /* ⛔ NEVER COMPLETE ON A FAILURE. The first batch stays on screen and everything that needs the
         whole list stays off; Retry runs this half again. */
      setLeadLoad((s) => ({ phase: 'failed', loaded: latestRef.current.active.length, total: s.total, error: message }));
    }
  }, []);

  /* ── THE PROGRESSIVE FIRST LOAD (Outreach page) ─────────────────────────────────────────────────
     One request for the newest OUTREACH_FIRST_BATCH active leads WITH the exact count (same source,
     same filter: a salesperson's count is their own view's), and the archived list alongside (small,
     and complete before anything shows, so it is never partial). Then the table appears, and the
     remaining pages load behind it. A list that fits in the first batch — every salesperson today —
     is complete at once. */
  const progressiveLoad = useCallback(async () => {
    const gen = ++loadGenRef.current;
    if (!hasLoadedOnceRef.current) setIsLoading(true);
    setLeadLoad(LEAD_LOAD_INITIAL);
    const src = leadSourceFor(roleRef.current);
    const sb = supabase as unknown as { from: (t: string) => any };
    let first: OutreachLead[] = [];
    let archived: OutreachLead[] = [];
    let total: number | null = null;
    try {
      const [p0, arc] = await Promise.all([
        sb.from(src.table).select(src.listSelect, { count: 'exact' }).eq('is_archived', false)
          .order('created_at', { ascending: false }).order('id', { ascending: true }).range(0, OUTREACH_FIRST_BATCH - 1),
        fetchAllRowsParallel<OutreachLead>('Outreach (archived leads)', (from, to) => sb
          .from(src.table).select(src.listSelect).eq('is_archived', true)
          .order('updated_at', { ascending: false }).order('id', { ascending: true }).range(from, to), (l) => l.id),
      ]);
      if (p0.error) throw p0.error;
      first = guardListRows((p0.data ?? []) as OutreachLead[], 'useOutreach');
      total = typeof p0.count === 'number' ? p0.count : null;
      archived = guardListRows(arc.rows, 'useOutreach');
    } catch (e) {
      if (gen !== loadGenRef.current) return;
      hasLoadedOnceRef.current = true;
      setIsLoading(false);
      const message = errorMessageOf(e);
      console.error('Error fetching leads:', e);
      setLeadLoad({ phase: 'failed', loaded: 0, total: null, error: message });
      toast({ ...leadLoadErrorText(e), variant: 'destructive' });
      return;
    }
    if (gen !== loadGenRef.current) return;
    shownRef.current = { active: first, archived, first, total };
    setLeads(first);
    setArchivedLeads(archived);
    hasLoadedOnceRef.current = true;
    setIsLoading(false);
    // Complete at once only when the count says the first batch IS the list.
    if (first.length === 0 || (total != null && first.length >= total && first.length < OUTREACH_FIRST_BATCH)) {
      setLeadLoad(LEAD_LOAD_COMPLETE(first.length));
      return;
    }
    setLeadLoad({ phase: 'partial', loaded: first.length, total, error: null });
    await loadRemainingLeads(gen);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [loadRemainingLeads]);

  /** The notice's Retry: the background half again if the first batch is on screen, else the lot. */
  const retryLeadLoad = useCallback(async () => {
    if (leadLoadRef.current.phase !== 'failed') return;
    if (leadLoadRef.current.fromLastVisit) {
      /* The last visit's list is still on screen: run the fresh full load again over it (still locked). */
      const st: LeadLoadState = { ...leadLoadRef.current, phase: 'partial', error: null };
      leadLoadRef.current = st;
      setLeadLoad(st);
      await fetchLeadsRef.current();
      return;
    }
    if (shownRef.current && shownRef.current.first.length > 0) {
      const gen = ++loadGenRef.current;
      setLeadLoad((s) => ({ ...s, phase: 'partial', error: null }));
      await loadRemainingLeads(gen);
    } else {
      await progressiveLoad();
    }
  }, [loadRemainingLeads, progressiveLoad]);

  const fetchLeadsRef = useRef<() => Promise<void>>(async () => {});
  const fetchLeads = useCallback(async () => {
    const uid = userIdRef.current;
    if (!uid) return;
    if (!preload) return; // Find Leads: never the whole book (see preload above)
    if (onlyLeadId) {
      /* The Inbox's lead dialog: one row, not the book (see onlyLeadId above). */
      const gen = ++loadGenRef.current;
      if (!hasLoadedOnceRef.current) setIsLoading(true);
      const src = leadSourceFor(roleRef.current);
      const { data, error } = await (supabase as unknown as { from: (t: string) => any })
        .from(src.table).select(src.listSelect).eq('id', onlyLeadId).eq('is_archived', false).maybeSingle();
      if (gen !== loadGenRef.current) return;
      hasLoadedOnceRef.current = true;
      setIsLoading(false);
      if (error) {
        console.error('Error fetching lead:', error);
        setLeadLoad((s) => ({ ...s, phase: 'failed', error: errorMessageOf(error) }));
        toast({ ...leadLoadErrorText(error), variant: 'destructive' });
        return;
      }
      const rows = data ? guardListRows([data as OutreachLead], 'useOutreach') : [];
      setLeads(rows);
      setArchivedLeads([]);
      setLeadLoad(LEAD_LOAD_COMPLETE(rows.length));
      return;
    }
    /* Progressive only while the list is not yet complete; a refresh of a COMPLETE list (after a bulk
       job, an import, a claim) reloads it whole in the background and swaps it in, so the page never
       drops back to "loading" and never re-locks the bulk actions. */
    if (progressive && !datasetComplete(leadLoadRef.current)) {
      /* ⚡ Coming back to Outreach (Paul, 2026-10-15; src/lib/outreachListMemory.ts): the list from the last visit goes on
         screen at once as LEAD_LOAD_FROM_LAST_VISIT — partial, so every whole-list action stays locked — and the full
         fresh load below replaces it (mergeAfterBackgroundLoad keeps anything edited meanwhile). No memory → as before. */
      const remembered = !hasLoadedOnceRef.current ? recallOutreachList<OutreachLead>(uid, roleRef.current) : null;
      if (remembered) {
        latestRef.current = { active: remembered.active, archived: remembered.archived };
        shownRef.current = null;
        setLeads(remembered.active);
        setArchivedLeads(remembered.archived);
        const st = LEAD_LOAD_FROM_LAST_VISIT(remembered.active.length);
        leadLoadRef.current = st;
        setLeadLoad(st);
        hasLoadedOnceRef.current = true;
        setIsLoading(false);
      } else if (!leadLoadRef.current.fromLastVisit) {
        await progressiveLoad();
        return;
      }
    }
    const gen = ++loadGenRef.current;
    /* What was on screen when this load started. A lead added (or removed) while the load runs must survive
       it: Find Leads loads the whole book here, and pressing Add to CRM during that load used to have its new
       row wiped by the stale result, so the button came back and a second press said "Previously added". */
    const shownAtStart = latestRef.current;
    
    // Only show loading spinner on initial load
    if (!hasLoadedOnceRef.current) {
      setIsLoading(true);
    }
    
    /* Paginated. Neither of these was, and they feed the whole /outreach table — including the
       "Paid (money in)" filter, which is now the only place paying customers are listed at all
       (/paid-clients was deleted 2026-08-12). At ~592 active leads a silent truncation at the
       1000-row cap would quietly shrink it, and the row it drops could be a customer — the Inbox's
       identical read did exactly that to RG Locksmiths.
       fetchAllRows throws on error, so the two error variables below stay for the
       existing handling and are only ever set by the catch. .order('id') is the unique tiebreaker. */
    let activeData: OutreachLead[] = [];
    let archivedData: OutreachLead[] = [];
    let activeError: unknown = null;
    let archivedError: unknown = null;
    try {
      /* ⚡ Pages fetched six at a time, and active + archived together (2026-09-27): the six
         sequential round trips were ~9 s of the Outreach page's load. Same rows, same order. */
      /* ⚡ The LIST columns, not '*' (2026-09-27): 41 of 111, 15.7 MB → 6.8 MB of JSON. What is and
         is not downloaded, and the three guards that keep a missing field from going quiet, are in
         src/lib/outreachLeadColumns.ts. The detail dialog reads its own complete row. */
      /* The admin reads the table; a salesperson reads the safe view (their own prospects only). */
      const src = leadSourceFor(roleRef.current);
      const [act, arc] = await Promise.allSettled([
        fetchAllRowsParallel<OutreachLead>('Outreach (active leads)', (from, to) => (supabase as unknown as { from: (t: string) => any })
          .from(src.table).select(src.listSelect).eq('is_archived', false)
          .order('created_at', { ascending: false }).order('id', { ascending: true }).range(from, to), (l) => l.id),
        fetchAllRowsParallel<OutreachLead>('Outreach (archived leads)', (from, to) => (supabase as unknown as { from: (t: string) => any })
          .from(src.table).select(src.listSelect).eq('is_archived', true)
          .order('updated_at', { ascending: false }).order('id', { ascending: true }).range(from, to), (l) => l.id),
      ]);
      if (act.status === 'fulfilled') activeData = guardListRows(act.value.rows, 'useOutreach');
      else activeError = act.reason ?? new Error('Unknown error');
      if (arc.status === 'fulfilled') archivedData = guardListRows(arc.value.rows, 'useOutreach');
      else archivedError = arc.reason ?? new Error('Unknown error');
    } catch (e) { activeError = e ?? new Error('Unknown error'); }

    hasLoadedOnceRef.current = true;
    setIsLoading(false);

    if (activeError) {
      console.error('Error fetching active leads:', activeError);
      if (gen !== loadGenRef.current) return;
      /* A refresh of a COMPLETE list that fails keeps the list it has (still complete); a first load says failed. */
      if (!datasetComplete(leadLoadRef.current)) setLeadLoad((s) => ({ ...s, phase: 'failed', error: errorMessageOf(activeError) }));
      toast({ ...leadLoadErrorText(activeError), variant: 'destructive' });
      return;
    }

    if (archivedError) {
      console.error('Error fetching archived leads:', archivedError);
    }

    if (gen !== loadGenRef.current) return;
    /* Lay the result over anything done while it loaded (the same rule as the Outreach background load):
       a lead added meanwhile stays, an edit stays, a removal stays removed. A failed archived read keeps the
       archived list as it was rather than emptying it. */
    const merged = mergeAfterBackgroundLoad({
      shownActive: shownAtStart.active, shownArchived: shownAtStart.archived,
      localActive: latestRef.current.active, localArchived: latestRef.current.archived,
      fetchedActive: activeData, fetchedArchived: archivedError ? latestRef.current.archived : archivedData,
    });
    setLeads(merged.active);
    setArchivedLeads(merged.archived);
    setLeadLoad(LEAD_LOAD_COMPLETE(merged.active.length));
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [progressive, progressiveLoad, preload, onlyLeadId]);
  fetchLeadsRef.current = fetchLeads;

  /* Remember the COMPLETE Outreach list for the next visit in this tab (outreachListMemory.ts) — every change to it too,
     so a return shows the list as it was left. Only the Outreach page (progressive) remembers. */
  useEffect(() => {
    if (!progressive || !user?.id || !datasetComplete(leadLoad)) return;
    rememberOutreachList(user.id, role, leads, archivedLeads);
  }, [progressive, user?.id, role, leadLoad, leads, archivedLeads]);

  const fetchOutreachHistory = useCallback(async (): Promise<OutreachHistoryEntry[] | null> => {
    const uid = userIdRef.current;
    if (!uid) return null;

    /* ⛔ PAGINATED (2026-09-27). It was one unordered select, so PostgREST silently returned 1,000 of
       the 5,333 rows and the add-lead pre-filter could not see the rest. The database dedupe stays the
       authority; this is the fast local pre-check, and now it sees everything. */
    let data: OutreachHistoryEntry[] = [];
    try {
      data = (await fetchAllRowsParallel<OutreachHistoryEntry & { id: string }>('Outreach (history)', (from, to) => supabase
        .from('outreach_history').select('id, business_name, google_maps_url, country')
        .order('id', { ascending: true }).range(from, to), (h) => h.id)).rows;
    } catch (error) {
      console.error('Error fetching outreach history:', error);
      return null;
    }

    setOutreachHistory(data as OutreachHistoryEntry[]);
    return data;
  }, []);

  const fetchActivities = useCallback(async (leadId: string) => {
    const { data, error } = await supabase
      .from('outreach_activities')
      .select('*')
      .eq('lead_id', leadId)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Error fetching activities:', error);
      return [];
    }

    return data as OutreachActivity[];
  }, []);

  // Only refetch when user ID changes (login/logout), not on token refresh
  useEffect(() => {
    const currentUserId = user?.id ?? null;
    if (currentUserId === userIdRef.current) return;
    userIdRef.current = currentUserId;
    if (!currentUserId) forgetOutreachList(); // signed out: the remembered list goes with the session
    if (currentUserId) {
      if (!preload) { setIsLoading(false); return; }
      fetchLeads();
      if (history) fetchOutreachHistory();
    }
  }, [user?.id, fetchLeads, fetchOutreachHistory, history, preload]);

  /* Without the list, the coverage watch above never sees a change, so an add or a removal made here
     marks Coverage stale through the events the page already fires (addLead and removeFreshLead fire
     crm-lead-added; a lead dropped for having no phone or email fires crm-lead-purged). */
  useEffect(() => {
    if (preload) return;
    const stale = () => { void queryClient.invalidateQueries({ queryKey: coverageQueryKey(user?.id) }); };
    window.addEventListener('crm-lead-added', stale);
    window.addEventListener('crm-lead-purged', stale);
    return () => { window.removeEventListener('crm-lead-added', stale); window.removeEventListener('crm-lead-purged', stale); };
  }, [preload, queryClient, user?.id]);

  // Resolve loading immediately for unauthenticated (ad-entry) users
  useEffect(() => {
    if (!user) {
      setIsLoading(false);
    }
  }, [user]);

  // REMOVED: Auto-enrichment on page load was removed to prevent unnecessary Google Place Details API calls.
  // Phone enrichment now only happens when: (1) lead first added to CRM, (2) manual retry, (3) bulk recover phones.

  // Retry phone fetch for a lead that failed — uses forceRefresh to bypass cache
  const retryPhoneFetch = useCallback(async (outreachLeadId: string) => {
    if (isSales()) { refuseForSales('Looking up a phone number'); return; }
    const lead = leads.find(l => l.id === outreachLeadId) || archivedLeads.find(l => l.id === outreachLeadId);
    if (!lead) return;
    
    const placeId = (lead as any).place_id;
    if (!placeId) {
      toast({
        title: 'Retry not available',
        description: 'No Place ID stored for this lead.',
        variant: 'destructive',
      });
      return;
    }
    
    // Direct call with forceRefresh instead of queue (user-initiated retry)
    setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'pending' }));
    try {
      const { data: details, error: detailsError } = await supabase.functions.invoke('google-place-details', {
        body: { placeId, forceRefresh: true, triggerSource: 'manual_retry' },
      });

      if (detailsError || !details) {
        setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'failed' }));
        toast({ title: 'Retry failed', description: 'Could not fetch phone number.', variant: 'destructive' });
        return;
      }

      // Store everything the lookup returned before branching on the phone — same reason as
      // fetchOnePhone: the address, town and rating are paid for whether or not there is a phone.
      const updated = await applyPlaceDetailsToLead(outreachLeadId, details as PlaceDetailsResponse);
      if (updated) {
        setLeads(prev => prev.map(l => l.id === outreachLeadId ? updated : l));
        setArchivedLeads(prev => prev.map(l => l.id === outreachLeadId ? updated : l));
      }

      if (!details.phone) {
        // No phone available even after force-refresh. Keep the lead.
        setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'no_phone' }));
        toast({ title: 'No phone available', description: 'Google has no phone number for this business.' });
        return;
      }

      setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'success' }));
    } catch (e) {
      console.error('Retry phone fetch failed:', e);
      setPhoneFetchStatus(prev => ({ ...prev, [outreachLeadId]: 'failed' }));
    }
  }, [leads, archivedLeads, removeLeadNoPhone]);

  const addLead = useCallback(async (lead: Lead, country: Country = 'UK', listType: ListType = 'no_website', campaignId: string | null = null, enrichment?: Partial<OutreachLead> | null, silent = false, searchKeyword: string | null = null, searchLocation: string | null = null) => {
    if (!user) {
      toast({
        title: 'Not authenticated',
        description: 'Please log in to add leads.',
        variant: 'destructive',
      });
      return null;
    }

    /* ══ NO TRADE, NO LEAD — Paul's call 2026-08-20: BLOCK, do not prompt ═══════════════════════
       ⛔ WHAT THIS PREVENTS. `search_keyword` is the trade every audit entry point reads, and a lead
       written without it CANNOT be audited at all — create-ai-audit needs a business type and there
       is none. 154 rows in the CRM are in exactly that state (measured 2026-08-20), 140 of them from
       the pre-2026-08-08 bug where the results outlived the search that produced them.
       That bug is fixed structurally (results and their search are now one persisted object), but the
       fix cannot cover results on screen with NO search behind them at all — a restored view, or a
       list populated by something other than a search. Then `lastSearch` is legitimately null, and
       until now addLead faithfully wrote the null through. 14 leads got that on 17 and 20 August.

       ⛔ BLOCKING, NOT PROMPTING, and that is deliberate. A prompt is a new dialog on the hottest
       path in the app, asking for something the page can almost always supply by itself — and the
       remedy here is one keypress (press Search). Refusing with the reason costs a click; guessing
       or nagging costs a lead that looks fine and cannot be audited. Same shape as addLead's
       fail-closed dedupe directly below: refuse rather than write something wrong.

       ⛔ THE GUARD IS HERE, NOT IN THE THREE Index CALL SITES. All four callers funnel through this
       function — Index (row / bulk / campaign dialog), MarketPanel and Coverage — and the panel and
       Coverage always pass a real trade. One guard at the choke point cannot be forgotten by a new
       call site; three guards at the call sites is the same class of bug this is fixing.
       ⚠️ Silent bulk adds must NOT toast 20 times. The message goes out once per call, and a bulk
       caller passes silent=true, so the batch reports its own skipped count as it already does. */
    if (!searchKeyword || !searchKeyword.trim()) {
      if (!silent) {
        toast({
          title: 'Run a search first',
          description:
            `${lead.name} was NOT added. These results have no search behind them, so the trade would be saved blank and the lead could never be audited. Search for the trade and town, then add.`,
          variant: 'destructive',
        });
      }
      return null;
    }

    /* ══ A SALESPERSON ADDS THROUGH THE SERVER, NEVER STRAIGHT INTO THE TABLE (multi-user, 2026-09-27)
       ⛔ ONE BUSINESS = ONE RECORD, decided by the database across EVERY user's leads — not by this
       hook's arrays, which for a salesperson hold nothing (they cannot read outreach_leads at all).
       sales_add_lead matches place id, phone and Maps URL, refuses an existing business and says
       whose it is, and otherwise inserts it into the one book, assigned to the rep. The admin's path
       below is unchanged. */
    if (roleRef.current === 'sales') {
      /* ⛔ THE PHONE COMES FROM PLACE DETAILS, LOOKED UP BEFORE THE ADD (2026-09-28). Google's text
         search returns no phone number (search-leads' field mask has none), so `lead.phone` is empty
         on every search result. The admin's add gets it from the lookup queued AFTER its insert,
         which writes the row directly — a salesperson cannot write outreach_leads, so for them that
         step never ran and every lead they added arrived with no phone. The same role-checked lookup
         now runs first and its values ride in the one add (salesAddPayload), which also lets the
         server's phone dedupe see the real number. The admin's rule for a business with neither a
         phone nor an email is kept: not added. A FAILED lookup never blocks the add. */
      const details = lead.id && (!lead.phone || !lead.address)
        ? await lookupPlaceDetails(lead.id)
        : null;
      const email = String(enrichment?.email ?? '').trim() || null;
      if (details && !details.phone && !lead.phone && !String(details.email ?? '').trim() && !email) {
        if (!silent) toast({ title: lead.name, description: 'No phone or email found — not added.', variant: 'destructive' });
        return null;
      }
      const { data: res, error: rpcErr } = await (supabase.rpc as unknown as (n: string, a: unknown) => Promise<{ data: unknown; error: { message?: string } | null }>)('sales_add_lead', {
        _lead: salesAddPayload({
          lead, details, email, searchKeyword, searchLocation, country, listType, campaignId,
        }),
      });
      const r = (res ?? null) as { ok?: boolean; error?: string; lead_id?: string; owner_name?: string | null } | null;
      if (rpcErr || !r?.ok) {
        if (!silent) toast({ title: 'Not added', description: lead.name + ': ' + refusalText(rpcErr?.message ?? r?.error, r?.owner_name), variant: 'destructive' });
        return null;
      }
      window.dispatchEvent(new CustomEvent('crm-lead-added'));
      window.dispatchEvent(new CustomEvent('sales-lead-changed'));
      recordSearchAddition(lead);
      if (!silent) toast({ title: 'Added to My leads', description: lead.name });
      return { id: r.lead_id, business_name: lead.name } as unknown as OutreachLead;
    }

    /* ⛔ A NAME IS ONLY A DUPLICATE IN THE SAME COUNTRY (2026-09-28). "Smile Dental Clinic" in Pune is
       not the one in Leeds. The Maps URL and place id stay country-blind: they ARE the business.
       A null country is the column default, UK. */
    const sameCountry = (c: string | null | undefined) => (c || 'UK') === (country || 'UK');
    // Fast local-only duplicate check (no DB round-trips)
    const inHistory = outreachHistory.some(
      (h) => (h.business_name === lead.name && sameCountry(h.country)) || (lead.googleMapsUrl && h.google_maps_url === lead.googleMapsUrl)
    );
    if (inHistory) {
      if (!silent) toast({
        title: 'Previously added',
        description: `${lead.name} was already added to your outreach list before.`,
        variant: 'destructive',
      });
      return null;
    }

    const inActive = leads.some(
      (l) => (l.business_name === lead.name && sameCountry(l.country)) || (lead.googleMapsUrl && l.google_maps_url === lead.googleMapsUrl)
    );
    const inArchived = archivedLeads.some(
      (l) => (l.business_name === lead.name && sameCountry(l.country)) || (lead.googleMapsUrl && l.google_maps_url === lead.googleMapsUrl)
    );
    if (inActive || inArchived) {
      const message = inArchived
        ? `${lead.name} is in your archive.`
        : `${lead.name} is already in your outreach list.`;
      if (!silent) toast({
        title: 'Previously added',
        description: message,
        variant: 'destructive',
      });
      return null;
    }

    /* ⛔ THE DATABASE IS THE DEDUPE; THE ARRAYS ABOVE ARE ONLY A FAST PRE-FILTER — fixed
       2026-08-18 after 25 duplicate cold openers. The in-memory scan races this hook's own async
       fetch: pressed before the list loads, an EMPTY list read as "no duplicates exist", and the
       Coverage add-all re-added fourteen Birkenhead businesses inserted two hours earlier (same
       names, same place_ids). Absence is never an answer — the live table decides.
       Three cheap keyed reads, first hit wins: place_id (pool adds always carry one; caught 20 of
       the 25), exact phone (CSV/search adds carry one; the pool's rows do not, which is why the
       queue's phone-history seatbelt exists as the second layer), then exact name (preserves the
       pre-filter's semantics). Archived rows count — an archived duplicate is still a duplicate.
       ⚠️ FAILS CLOSED: if the checks themselves error, the lead is NOT added — a refusal costs one
       retry; the open direction is this incident. */
    try {
      let existing: { id: string; business_name: string; is_archived: boolean | null } | null = null;
      if (lead.id) {
        const { data, error: e } = await supabase.from('outreach_leads')
          .select('id, business_name, is_archived').eq('place_id', lead.id).limit(1).maybeSingle();
        if (e) throw e;
        existing = data ?? null;
      }
      if (!existing && lead.phone) {
        const { data, error: e } = await supabase.from('outreach_leads')
          .select('id, business_name, is_archived').eq('phone', lead.phone).limit(1).maybeSingle();
        if (e) throw e;
        existing = data ?? null;
      }
      if (!existing) {
        /* Same name, same country only (see sameCountry above); UK also matches the null default. */
        const nameQ = supabase.from('outreach_leads')
          .select('id, business_name, is_archived').eq('business_name', lead.name);
        const { data, error: e } = await ((country || 'UK') === 'UK'
          ? nameQ.or('country.is.null,country.eq.UK')
          : nameQ.eq('country', country)).limit(1).maybeSingle();
        if (e) throw e;
        existing = data ?? null;
      }
      if (existing) {
        if (!silent) toast({
          title: 'Previously added',
          description: `${lead.name} is already in your ${existing.is_archived ? 'archive' : 'outreach list'} (as "${existing.business_name}").`,
          variant: 'destructive',
        });
        return null;
      }
      /* Without the preloaded history (Find Leads) the in-memory pre-check above saw nothing: ask the database
         the same question for this one business — same name in the same country, or the same Maps link. */
      if (!preload) {
        const { data: byName, error: hErr } = await supabase.from('outreach_history')
          .select('id, country').eq('business_name', lead.name).limit(20);
        if (hErr) throw hErr;
        let inHist = (byName ?? []).some((h) => sameCountry((h as { country?: string | null }).country));
        if (!inHist && lead.googleMapsUrl) {
          const { data: byUrl, error: uErr } = await supabase.from('outreach_history')
            .select('id').eq('google_maps_url', lead.googleMapsUrl).limit(1);
          if (uErr) throw uErr;
          inHist = (byUrl ?? []).length > 0;
        }
        if (inHist) {
          if (!silent) toast({
            title: 'Previously added',
            description: `${lead.name} was already added to your outreach list before.`,
            variant: 'destructive',
          });
          return null;
        }
      }
    } catch {
      if (!silent) toast({
        title: 'Could not check for duplicates',
        description: `${lead.name} was NOT added — the duplicate check itself failed. Try again.`,
        variant: 'destructive',
      });
      return null;
    }

    // Carry over any contact enrichment already found at search time. The
    // enrich-lead cache is keyed by place_id, so these values are free here — no
    // new paid call is made on add. Only copy fields the engine actually set.
    const carriedEnrichment: Partial<OutreachLead> = {};
    if (enrichment) {
      const carryKeys: (keyof OutreachLead)[] = [
        'email', 'email_status', 'email_method', 'email_last_checked_at',
        'facebook_url', 'facebook_status', 'facebook_method', 'facebook_last_checked_at',
        'instagram_url', 'instagram_status', 'instagram_method', 'instagram_last_checked_at',
        'enrichment_source',
      ];
      for (const k of carryKeys) {
        if (enrichment[k] != null) (carriedEnrichment as any)[k] = enrichment[k];
      }
    }

    const { data, error } = await supabase
      .from('outreach_leads')
      .insert({
        user_id: user.id,
        /* ⛔ THE PERSON WHO ADDS IT OWNS IT (Paul, 2026-10-05). Without these, every lead Paul added from Find Leads
           or Coverage landed UNASSIGNED. The database stamps the same owner itself (trigger
           trg_outreach_leads_added_by_owner, migration 20261009160000) — this is only so the right owner shows
           at once; the server, not this line, is the rule. A salesperson never reaches this insert (sales_add_lead). */
        assigned_to_user_id: user.id,
        assigned_at: new Date().toISOString(),
        added_by_user_id: user.id,
        business_name: lead.name,
        // Save the phone we already have from the search result. This avoids
        // a Place Details call entirely when the search already returned one.
        phone: lead.phone || null,
        email: null,
        google_maps_url: lead.googleMapsUrl,
        address: lead.address || null,
        category: lead.category || null,
        search_keyword: searchKeyword || null,
        search_location: searchLocation || null,
        website: lead.websiteUrl || null,
        status: 'not_contacted' as LeadStatus,
        next_action: 'none' as NextActionType,
        next_action_date: null,
        country,
        list_type: listType,
        campaign_id: campaignId,
        place_id: lead.id || null,
        ...carriedEnrichment,
      } as any)
      .select()
      .single();

    if (error) {
      toast({
        title: 'Error adding lead',
        description: error.message,
        variant: 'destructive',
      });
      return null;
    }

    const newLead = data as OutreachLead;
    setLeads((prev) => [newLead, ...prev]);
    /* Seen at once by a list load that lands before the next render (fetchLeads merges against latestRef). */
    latestRef.current = { ...latestRef.current, active: [newLead, ...latestRef.current.active] };
    recordSearchAddition(lead);

    // Notify bottom nav immediately
    window.dispatchEvent(new CustomEvent('crm-lead-added'));

    // If the user navigates straight to Outreach after adding, ensure they land on page 1.
    try {
      const key = user?.id ? `leadfinder_outreach_force_page1:${user.id}` : 'leadfinder_outreach_force_page1';
      sessionStorage.setItem(key, '1');
      localStorage.setItem(key, '1');
    } catch {
      // ignore
    }

    // Update local history cache immediately
    setOutreachHistory((prev) => [...prev, { 
      business_name: lead.name, 
       google_maps_url: lead.googleMapsUrl || null,
       phone: lead.phone || null,
    }]);

    // Fire-and-forget: history insert, activity log, usage tracking (non-blocking)
    Promise.resolve(supabase.from('outreach_history').insert({
      user_id: user.id,
      business_name: lead.name,
      google_maps_url: lead.googleMapsUrl || null,
      country,
       phone: lead.phone || null,
    })).catch(() => {});

    logActivity(newLead.id, 'added', `Added ${lead.name} to outreach list`).then(() => {}).catch(() => {});

    Promise.resolve(supabase.rpc('log_usage_event', {
      p_event_type: 'business_added',
      p_meta: {
        place_id: lead.id || null,
        business_name: lead.name,
        country,
        source: 'add-business',
      },
    })).catch(() => {});

    // Lead added — no toast

    /* Enqueue a single Place Details lookup (server-side cache + single-flight).
       GATED ON EVERYTHING THE LOOKUP PROVIDES, not on the phone alone. It used to skip whenever the
       search result carried a phone — and the phone was the only thing it fetched, so that was
       consistent. It no longer is: the same call now returns the address, the derived town, the
       rating and the review count. Keeping the old test would mean that the day anyone adds
       `places.nationalPhoneNumber` to search-leads' field mask, every new lead silently loses its
       town again and the audit box goes blank exactly as it did before this fix. The search mask
       returns none of these today, so in practice this always fires — the point is that it stays
       correct if that changes. */
    const needsLookup = !lead.phone || !lead.address || lead.rating == null || lead.reviewCount == null;
    if (lead.id && needsLookup) {
      // Pass the lead's email (carried enrichment lands on newLead.email) so a
      // no-phone lead with an email is KEPT, not dropped.
      enqueuePhoneFetch(newLead.id, lead.id, lead.name, newLead.email);
    } else if (lead.id) {
      console.log(`Skipping enrichment for ${lead.name}: search result already carried phone, address, rating and reviews`);
    }

    return newLead;
  }, [user]);

  /* ⛔ ONE ADD PER BUSINESS AT A TIME (2026-10-13). A second press of Add to CRM for a business whose add is
     still running (a double click, or a press while the slow lead list loads) joins the SAME add and gets its
     answer; it never starts a second insert and is never dropped. The database dedupe stays the authority
     for anything already saved. */
  const addsInFlightRef = useRef(new Map<string, Promise<OutreachLead | null>>());
  const addLeadSingleFlight = useCallback((lead: Lead, ...rest: Parameters<typeof addLead> extends [Lead, ...infer R] ? R : never) => {
    const key = addInFlightKey(lead);
    const running = addsInFlightRef.current.get(key);
    if (running) return running;
    const p = addLead(lead, ...rest).finally(() => { addsInFlightRef.current.delete(key); });
    addsInFlightRef.current.set(key, p);
    return p;
  }, [addLead]);

  const updateLead = useCallback(async (
    leadId: string,
    updates: Partial<Pick<OutreachLead, 'status' | 'next_action' | 'next_action_date' | 'notes' | 'email' | 'business_name' | 'phone' | 'address' | 'amount_paid' | 'paid_for' | 'payment_date' | 'project_duration' | 'next_checkin_date' | 'checkin_notes' | 'image_url' | 'facebook_url' | 'facebook_confidence' | 'facebook_method' | 'facebook_last_checked_at' | 'email_status' | 'email_method' | 'email_last_checked_at' | 'facebook_status' | 'instagram_url' | 'instagram_status' | 'instagram_method' | 'instagram_last_checked_at' | 'enrichment_source' | 'contact_method' | 'whatsapp_status' | 'whatsapp_checked_at' | 'line_type' | 'line_type_checked_at' | 'outreach_attempts' | 'last_outreach_attempt_at' | 'is_potential_work' | 'potential_revenue' | 'contact_name' | 'website' | 'services_included' | 'confirmed_services' | 'whatsapp_template' | 'queued_at' | 'contact_followup_queued_at' | 'whatsapp_attempts' | 'project_overview' | 'project_value' | 'project_status' | 'delivery_notes' | 'remeasure_due_date' | 'delivery_checklist' | 'delivery_ref'>>
  ) => {
    if (isSales()) return salesUpdateLead(leadId, updates as Record<string, unknown>);
    const { data, error } = await supabase
      .from('outreach_leads')
      .update(updates)
      .eq('id', leadId)
      .select()
      .single();

    if (error) {
      toast({
        title: 'Error updating lead',
        description: error.message,
        variant: 'destructive',
      });
      return null;
    }

    const updatedLead = data as OutreachLead;

    /* ⛔ MARKING SOMEONE NOT INTERESTED NOW ACTUALLY STOPS CONTACT.
       🔴 UNTIL 2026-09-02 IT DID NOTHING BEYOND RELABELLING THE ROW. The app has never written a
       contact_suppressions row - it only read that table, and blindly (the RLS-with-no-policies
       trap, CLAUDE.md §8). Every one of the 28 suppressions on file came from whatsapp-inbound
       auto-detecting a decline in a reply; not one came from an operator. So four numbers whose
       leads said not_interested were sent audit_result_hook that afternoon, and the send-time
       suppression guard had nothing to match on.

       ⚠️ ROUTED THROUGH THE EDGE FUNCTION BECAUSE THE SPA PHYSICALLY CANNOT WRITE THIS TABLE.
       A direct insert would return 200 and create nothing - the same silent no-op being fixed.

       ⚠️ FIRED ONLY WHEN THE STATUS IS ACTUALLY BEING SET, not on every update that happens to
       carry a lead whose status is already not_interested. `updates.status` is the operator's
       intent; `updatedLead.status` is just the row.

       ⚠️ NOT AWAITED INTO THE RETURN VALUE, and never fatal. Suppression is a promise about future
       contact, not part of saving this row - if the endpoint is down, the status change must still
       land. It is logged loudly instead, because a suppression that silently failed is precisely the
       bug above. The send-time guards remain the enforcement; this only supplies what they read. */
    if (updates.status === 'not_interested' || updates.status === 'closed') {
      const reason = updates.status;
      void supabase.functions
        .invoke('process-whatsapp-queue', { body: { mode: 'suppress_lead', lead_id: leadId, reason } })
        .then(({ data: sd, error: se }) => {
          const okRow = (sd as { ok?: boolean } | null)?.ok === true;
          if (se || !okRow) {
            console.error(`[useOutreach] suppression write FAILED for lead ${leadId} (${reason}) - this business is not yet protected from future contact`, se ?? sd);
            toast({
              title: 'Status saved, but contact block failed',
              description: 'The lead is marked, but nothing is stopping future outreach to this number yet. Try again or check the queue panel.',
              variant: 'destructive',
            });
          }
        });
    }

    // Update in correct list based on archived status
    if (updatedLead.is_archived) {
      setArchivedLeads((prev) => prev.map((l) => (l.id === leadId ? updatedLead : l)));
    } else {
      setLeads((prev) => prev.map((l) => (l.id === leadId ? updatedLead : l)));
    }
    notifyLeadChanged(leadId, syncOriginRef.current);

    return updatedLead;
  }, []);

  // Bulk-move selected leads to a campaign (or null = "No campaign"). ONE batched
  // write, owner-RLS scoped (only the caller's own rows are touched). Optimistically
  // patches both leads + archivedLeads lists so the move shows instantly (and leads
  // re-bucket under the page's campaign filter without a refetch).
  const assignCampaign = useCallback(async (leadIds: string[], campaignId: string | null, campaignName: string | null = null): Promise<boolean> => {
    if (leadIds.length === 0) return false;
    /* ⛔ A SALESPERSON MOVES THROUGH THE SAME RULE AS THE WORKSPACE'S CAMPAIGN CARD (2026-09-28):
       leads_set_campaign runs lead_set_campaign on each lead — own, non-client leads only, an existing
       campaign, the one campaign_id column, one activity row per change. A direct update here would be
       a silent 0-row "success" for them. The moved rows are then re-read from their view. */
    if (isSales()) {
      const r = await leadsSetCampaign(leadIds, campaignId);
      if (!r.ok) {
        toast({ title: 'Not moved', description: refusalText(r.error), variant: 'destructive' });
        return false;
      }
      const src = leadSourceFor('sales');
      const { data } = await (supabase as unknown as { from: (t: string) => any })
        .from(src.table).select(src.listSelect).in('id', leadIds);
      for (const row of (data ?? []) as OutreachLead[]) placeRow(row);
      for (const id of leadIds) notifyLeadChanged(id, syncOriginRef.current);
      const skipped = Object.values(r.skipped ?? {}).reduce((a, b) => a + b, 0);
      toast({ title: skipped ? 'Some leads not moved' : 'Moved', description: campaignMoveText(r, campaignName), variant: skipped ? 'destructive' : undefined });
      return (r.moved ?? 0) + (r.unchanged ?? 0) > 0;
    }
    const { error } = await supabase
      .from('outreach_leads')
      .update({ campaign_id: campaignId })
      .in('id', leadIds);
    if (error) {
      toast({ title: 'Could not move leads', description: error.message, variant: 'destructive' });
      return false;
    }
    const idSet = new Set(leadIds);
    const patch = (l: OutreachLead): OutreachLead => (idSet.has(l.id) ? { ...l, campaign_id: campaignId } : l);
    setLeads((prev) => prev.map(patch));
    setArchivedLeads((prev) => prev.map(patch));
    return true;
  }, []);

  /* "REMOVE FROM MY LEADS" — a salesperson only (2026-09-28). The server decides per lead
     (sales_remove_leads): never contacted → released (unassigned); contacted → archived and
     still theirs; clients, won/onboarding and queued leads refused. Nothing is deleted. Released rows
     leave both lists; archived ones are re-read and move to the archive. */
  const removeFromMyLeads = useCallback(async (leadIds: string[]): Promise<boolean> => {
    if (!isSales()) { toast({ title: 'Not available', description: 'The admin reassigns or removes leads instead.', variant: 'destructive' }); return false; }
    if (leadIds.length === 0) return false;
    const r = await salesRemoveLeads(leadIds);
    if (!r.ok) {
      toast({ title: 'Not removed', description: refusalText(r.error), variant: 'destructive' });
      return false;
    }
    const released = new Set((r.results ?? []).filter((x) => x.outcome === 'released').map((x) => x.id));
    const archived = (r.results ?? []).filter((x) => x.outcome === 'archived').map((x) => x.id);
    if (released.size) {
      setLeads((prev) => prev.filter((l) => !released.has(l.id)));
      setArchivedLeads((prev) => prev.filter((l) => !released.has(l.id)));
    }
    if (archived.length) {
      const src = leadSourceFor('sales');
      const { data } = await (supabase as unknown as { from: (t: string) => any })
        .from(src.table).select(src.listSelect).in('id', archived);
      for (const row of (data ?? []) as OutreachLead[]) placeRow(row);
    }
    for (const x of r.results ?? []) if (x.outcome !== 'refused') notifyLeadChanged(x.id, syncOriginRef.current);
    window.dispatchEvent(new CustomEvent('sales-lead-changed'));
    const skipped = Object.values(r.skipped ?? {}).reduce((a, b) => a + b, 0);
    toast({ title: skipped ? 'Some leads not removed' : 'Removed from your leads', description: removeOutcomeText(r), variant: skipped ? 'destructive' : undefined });
    return released.size + archived.length > 0;
  }, [placeRow]);

  const deleteLead = useCallback(async (leadId: string, silent = false) => {
    if (isSales()) { refuseForSales('Removing a lead'); return false; }
    const lead = leads.find((l) => l.id === leadId);
    const archivedLead = archivedLeads.find((l) => l.id === leadId);
    const targetLead = lead || archivedLead;
    
    const { error } = await supabase
      .from('outreach_leads')
      .delete()
      .eq('id', leadId);

    if (error) {
      toast({
        title: 'Error deleting lead',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

    setLeads((prev) => prev.filter((l) => l.id !== leadId));
    setArchivedLeads((prev) => prev.filter((l) => l.id !== leadId));

    // Lead removed — no toast

    return true;
  }, [leads, archivedLeads]);

  // Remove a FRESH/untouched lead (Find Leads "Remove" toggle). ADDITIVE — separate
  // from deleteLead (which other callers rely on and which doesn't clear history).
  // The DELETE only happens after a LIVE re-fetch confirms the lead is still fresh,
  // so a lead messaged/queued since page load can never be deleted here. On success
  // it also clears the outreach_history ledger + local cache + the team claim that
  // addLead created, so the business becomes re-addable.
  const removeFreshLead = useCallback(async (leadId: string): Promise<{ ok: boolean; reason?: string }> => {
    if (isSales()) { refuseForSales('Removing a lead'); return { ok: false, reason: 'admin_only' }; }
    if (!user) return { ok: false, reason: 'no_user' };

    // a) LIVE re-fetch of the freshness-relevant columns — never trust a stale flag.
    const { data: row, error: fErr } = await supabase
      .from('outreach_leads')
      .select('id, business_name, google_maps_url, place_id, campaign_id, status, next_action, whatsapp_sent_at, whatsapp_delivery_status, whatsapp_message_id, contact_method, notes, queued_at, last_outreach_attempt_at, outreach_attempts, is_potential_work')
      .eq('id', leadId)
      .maybeSingle();

    if (fErr) return { ok: false, reason: 'lookup_failed' };
    if (!row) {
      // Already gone — reconcile local state, report not_found.
      setLeads((prev) => prev.filter((l) => l.id !== leadId));
      setArchivedLeads((prev) => prev.filter((l) => l.id !== leadId));
      return { ok: false, reason: 'not_found' };
    }
    // Click-time guard: abort if it's been actioned since page load.
    if (!isFreshLead(row as Partial<OutreachLead>)) {
      return { ok: false, reason: 'not_fresh' };
    }

    // b) Delete the (still-fresh) lead row.
    const { error: dErr } = await supabase.from('outreach_leads').delete().eq('id', leadId);
    if (dErr) {
      toast({ title: 'Error removing lead', description: dErr.message, variant: 'destructive' });
      return { ok: false, reason: 'delete_failed' };
    }

    const name = (row as { business_name: string }).business_name;
    const mapsUrl = (row as { google_maps_url: string | null }).google_maps_url ?? null;

    // Clear the outreach_history ledger (by the same keys addLead wrote) so the
    // business can be re-added, then the local cache — mirrors removeLeadNoPhone.
    try {
      if (name) await supabase.from('outreach_history').delete().eq('business_name', name);
      if (mapsUrl) await supabase.from('outreach_history').delete().eq('google_maps_url', mapsUrl);
    } catch { /* best-effort */ }
    setOutreachHistory((prev) => prev.filter(
      (h) => h.business_name !== name && !(mapsUrl && h.google_maps_url === mapsUrl),
    ));

    // Local state — drop from active/archived.
    setLeads((prev) => prev.filter((l) => l.id !== leadId));
    setArchivedLeads((prev) => prev.filter((l) => l.id !== leadId));
    window.dispatchEvent(new CustomEvent('crm-lead-added')); // nudge the bottom-nav count to refresh

    return { ok: true };
  }, [user]);

  const updateStatus = useCallback(async (leadId: string, status: LeadStatus) => {
    if (status === 'not_interested') await clearNextActionOnNo(leadId); // both roles, before the archive
    /* Sales: the same patch, through the lead functions; not-interested also archives, as below. */
    if (isSales()) return salesUpdateLead(leadId, { ...statusUpdatePatch(status), ...(status === 'not_interested' ? { is_archived: true } : {}) });
    const lead = leads.find((l) => l.id === leadId);
    const archivedLead = archivedLeads.find((l) => l.id === leadId);
    const targetLead = lead || archivedLead;
    
    // Capture previous status BEFORE the update for outreach tracking
    const previousStatus = targetLead?.status;

    // The column changes for this status come from the shared patch (single source
    // of truth — the Inbox status pill writes the identical patch via updateLeadStatus):
    //   interested→star only · not_interested→untrack (is_potential_work=false). It never
    //   writes a next action — those are human-set only (src/lib/statusPatch.ts).
    const updates: Partial<OutreachLead> = statusUpdatePatch(status);

    const result = await updateLead(leadId, updates);
    
    // Log activity inline (avoid dependency issue with logActivity)
    if (result && targetLead && user) {
      try {
        await supabase.from('outreach_activities').insert({
          lead_id: leadId,
          user_id: user.id,
          activity_type: 'status_change',
          description: `Status changed to ${status.replace('_', ' ')}`,
        });
      } catch (e) {
        console.error('Failed to log activity (non-blocking):', e);
      }
      // Notify demo checklist that status was changed
      window.dispatchEvent(new CustomEvent('demo-checklist-status-change'));
      
      // Auto-increment messages_sent if transitioning FROM non-outreach TO outreach status
      const wasOutreach = previousStatus ? OUTREACH_STATUSES.includes(previousStatus) : false;
      const isNowOutreach = OUTREACH_STATUSES.includes(status);

      if (!wasOutreach && isNowOutreach) {
        try {
          await supabase.rpc('log_usage_event', {
            p_event_type: 'message_sent',
            p_meta: {
              lead_id: leadId,
              business_name: targetLead.business_name,
              status,
              source: 'status_change',
            },
          });
          // Emit event so dashboard/progress panels can update in real time
          window.dispatchEvent(new CustomEvent('outreach-message-sent'));
        } catch (e) {
          console.error('Failed to log message_sent (non-blocking):', e);
        }
      }
    }
    if (result && status === 'not_interested' && lead) {
      try {
        const { error } = await supabase
          .from('outreach_leads')
          .update({ is_archived: true })
          .eq('id', leadId);

        if (!error) {
          setLeads((prev) => prev.filter((l) => l.id !== leadId));
          setArchivedLeads((prev) => [{ ...lead, is_archived: true, is_potential_work: false, status: 'not_interested' }, ...prev]);
        }
      } catch (e) {
        console.error('Failed to auto-archive (non-blocking):', e);
      }
    }
    
    return result;
  }, [leads, archivedLeads, updateLead, user]);

  /* ⛔ THE ONE NEXT-ACTION WRITE, both roles (src/lib/nextActionWrite.ts → lead_set_follow_up, History
     "Follow-up set"), 2026-10-02. Used by the bulk "Set Action" menu and the Inbox's lead popup. A value not
     given keeps what the lead has (the bulk menu sets only the type: its day and note stay). It used to write
     the admin's row directly with no History line. */
  const updateNextAction = useCallback(async (
    leadId: string,
    nextAction: NextActionType,
    nextActionDate?: string,
    note?: string | null,
  ): Promise<OutreachLead | null> => {
    const lead = leads.find((l) => l.id === leadId) ?? archivedLeads.find((l) => l.id === leadId);
    const date = nextAction === 'none' ? null : (nextActionDate ?? lead?.next_action_date ?? null);
    const r = await saveNextAction(leadId, {
      nextAction,
      date,
      /* The time stays with its day: the bulk menu (type only) keeps it; a new day drops it. */
      time: date && date === lead?.next_action_date ? (lead?.next_action_time ?? null) : null,
      note: note === undefined ? (lead?.next_action_note ?? null) : note,
    });
    if (!r.ok) {
      toast({ title: 'Not saved', description: refusalText(r.error), variant: 'destructive' });
      return null;
    }
    return lead ? ({ ...lead, ...(r.patch ?? {}) } as OutreachLead) : null;
  }, [leads, archivedLeads]);

  const updateNotes = useCallback(async (leadId: string, notes: string) => {
    return updateLead(leadId, { notes });
  }, [updateLead]);

  const updateBusinessName = useCallback(async (leadId: string, businessName: string) => {
    return updateLead(leadId, { business_name: businessName });
  }, [updateLead]);


  const deleteAllLeads = useCallback(async () => {
    if (isSales()) { refuseForSales('Archiving every lead'); return false; }
   if (!user) return false;

    const { error } = await supabase
      .from('outreach_leads')
     .update({ is_archived: true })
     .eq('user_id', user.id)
     .eq('is_archived', false);

    if (error) {
      toast({
       title: 'Error archiving leads',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

   // Move all leads to archived list
   setArchivedLeads((prev) => [...leads.map(l => ({ ...l, is_archived: true })), ...prev]);
    setLeads([]);
    
    // All archived — no toast

    return true;
 }, [user, leads]);

  const logActivity = useCallback(async (
    leadId: string,
    activityType: string,
    description: string
  ) => {
    if (!user) return null;

    const { data, error } = await supabase
      .from('outreach_activities')
      .insert({
        lead_id: leadId,
        user_id: user.id,
        activity_type: activityType,
        description,
      })
      .select()
      .single();

    if (error) {
      console.error('Error logging activity:', error);
      return null;
    }

    return data as OutreachActivity;
  }, [user]);

  const isInOutreach = useCallback((leadName: string, googleMapsUrl?: string): boolean => {
    // Check against outreach history (includes all businesses ever added, even if deleted)
    const inHistory = outreachHistory.some(
      (h) => h.business_name === leadName || (googleMapsUrl && h.google_maps_url === googleMapsUrl)
    );
    
    // Also check active leads
    const inActive = leads.some(
      (l) => l.business_name === leadName || (googleMapsUrl && l.google_maps_url === googleMapsUrl)
    );
    
    // Also check archived leads
    const inArchived = archivedLeads.some(
      (l) => l.business_name === leadName || (googleMapsUrl && l.google_maps_url === googleMapsUrl)
    );
    
    return inHistory || inActive || inArchived;
  }, [outreachHistory, leads, archivedLeads]);

  // Internal archive function (can be silent)
  const archiveLeadInternal = useCallback(async (leadId: string, lead: OutreachLead, silent = false) => {
    if (isSales()) return !!(await salesUpdateLead(leadId, { is_archived: true }));
    const { error } = await supabase
      .from('outreach_leads')
      .update({ is_archived: true })
      .eq('id', leadId);

    if (error) {
      if (!silent) {
        toast({
          title: 'Error archiving lead',
          description: error.message,
          variant: 'destructive',
        });
      }
      return false;
    }

    // Move from active to archived
    setLeads((prev) => prev.filter((l) => l.id !== leadId));
    setArchivedLeads((prev) => [{ ...lead, is_archived: true }, ...prev]);
    
    // Lead archived — no toast

    return true;
  }, []);

  // Archive a single lead (public API)
  const archiveLead = useCallback(async (leadId: string) => {
    const lead = leads.find((l) => l.id === leadId);
    if (!lead) return false;
    return archiveLeadInternal(leadId, lead, false);
  }, [leads, archiveLeadInternal]);

  // Unarchive a single lead
  const unarchiveLead = useCallback(async (leadId: string) => {
    if (isSales()) return !!(await salesUpdateLead(leadId, { is_archived: false }));
    const lead = archivedLeads.find((l) => l.id === leadId);
    if (!lead) return false;

    const { error } = await supabase
      .from('outreach_leads')
      .update({ is_archived: false })
      .eq('id', leadId);

    if (error) {
      toast({
        title: 'Error unarchiving lead',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

    // Move from archived to active
    setArchivedLeads((prev) => prev.filter((l) => l.id !== leadId));
    setLeads((prev) => [{ ...lead, is_archived: false }, ...prev]);
    
    // Lead restored — no toast

    return true;
  }, [archivedLeads]);

  // Archive multiple leads
  const archiveMultiple = useCallback(async (leadIds: string[]) => {
    if (leadIds.length === 0) return false;
    if (isSales()) { for (const id of leadIds) await salesUpdateLead(id, { is_archived: true }); return true; }

    const { error } = await supabase
      .from('outreach_leads')
      .update({ is_archived: true })
      .in('id', leadIds);

    if (error) {
      toast({
        title: 'Error archiving leads',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

    // Move leads from active to archived
    const archivedItems = leads.filter((l) => leadIds.includes(l.id));
    setLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));
    setArchivedLeads((prev) => [...archivedItems.map(l => ({ ...l, is_archived: true })), ...prev]);
    
    // Leads archived — no toast

    return true;
  }, [leads]);

  // Delete multiple leads
  const deleteMultiple = useCallback(async (leadIds: string[]) => {
    if (isSales()) { refuseForSales('Removing leads'); return false; }
    if (leadIds.length === 0) return false;

    const { error } = await supabase
      .from('outreach_leads')
      .delete()
      .in('id', leadIds);

    if (error) {
      toast({
        title: 'Error removing leads',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

    setLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));
    setArchivedLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));

    // Leads removed — no toast

    return true;
  }, []);

  // RESET: fully wipe selected leads so they're as if never added — deletes the
  // outreach_leads rows AND clears their outreach_history ledger (by business_name
  // AND google_maps_url, the same keys isInOutreach matches on), so they become
  // re-addable on Find Leads. Generalises removeLeadNoPhone's history-clearing to
  // multi-select. DELIBERATELY different from deleteMultiple (which keeps the ledger
  // to prevent re-contacting).
  const resetMultiple = useCallback(async (leadIds: string[]) => {
    if (isSales()) { refuseForSales('Resetting leads'); return false; }
    if (leadIds.length === 0) return false;
    // Identity keys for the selected leads, captured from current state BEFORE delete.
    const sel = [...leads, ...archivedLeads].filter((l) => leadIds.includes(l.id));
    const names = [...new Set(sel.map((l) => l.business_name).filter(Boolean))];
    const mapsUrls = [...new Set(sel.map((l) => l.google_maps_url).filter(Boolean) as string[])];

    // (a) delete the outreach_leads rows
    const { error } = await supabase.from('outreach_leads').delete().in('id', leadIds);
    if (error) {
      toast({ title: 'Error resetting leads', description: error.message, variant: 'destructive' });
      return false;
    }

    // (b) clear the added-history ledger by BOTH keys → makes them re-addable
    if (names.length) await supabase.from('outreach_history').delete().in('business_name', names);
    if (mapsUrls.length) await supabase.from('outreach_history').delete().in('google_maps_url', mapsUrls);

    // (c) local state
    setLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));
    setArchivedLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));
    setOutreachHistory((prev) => prev.filter(
      (h) => !names.includes(h.business_name) && !(h.google_maps_url && mapsUrls.includes(h.google_maps_url)),
    ));

    toast({
      title: `Reset ${leadIds.length} lead${leadIds.length === 1 ? '' : 's'}`,
      description: 'Fully cleared (including added-history) — they can be added again on Find Leads.',
    });
    return true;
  }, [leads, archivedLeads]);

  // Reset the selected leads "to fresh": server-side (clear-enrichment-cache edge fn,
  // now extended) it DELETES each lead's generated site, NULLs only their enrichment
  // fields (FB/IG/email/line-type/etc.), and clears the enrichment_cache — while KEEPING
  // identity, notes, status, tracking (is_potential_work) and history. All service-role
  // (enrichment_cache + site delete need it) and ownership-guarded server-side. Distinct
  // from deleteMultiple/resetMultiple (which remove the lead) — those stay untouched.
  const resetToFreshMultiple = useCallback(async (leadIds: string[]) => {
    if (isSales()) { refuseForSales('Resetting leads to fresh'); return false; }
    if (leadIds.length === 0) return false;
    const sel = [...leads, ...archivedLeads].filter((l) => leadIds.includes(l.id));
    const businesses = sel.map((l) => ({
      placeId: l.place_id ?? null,
      googleMapsUrl: l.google_maps_url ?? null,
      leadId: l.id,
    }));
    const { error } = await supabase.functions.invoke('clear-enrichment-cache', {
      body: { businesses },
    });
    if (error) {
      toast({ title: 'Error resetting leads', description: error.message, variant: 'destructive' });
      return false;
    }
    // Re-fetch so the wiped enrichment fields + removed site reflect immediately.
    await fetchLeads();
    toast({
      title: `Reset ${businesses.length} lead${businesses.length === 1 ? '' : 's'} to fresh`,
      description: 'Site deleted, enrichment cleared. Identity, notes, status and history kept.',
    });
    return true;
  }, [leads, archivedLeads, fetchLeads]);

  // Unarchive multiple leads
  const unarchiveMultiple = useCallback(async (leadIds: string[]) => {
    if (leadIds.length === 0) return false;
    if (isSales()) { for (const id of leadIds) await salesUpdateLead(id, { is_archived: false }); return true; }

    const { error } = await supabase
      .from('outreach_leads')
      .update({ is_archived: false })
      .in('id', leadIds);

    if (error) {
      toast({
        title: 'Error unarchiving leads',
        description: error.message,
        variant: 'destructive',
      });
      return false;
    }

    // Move leads from archived to active
    const unarchivedItems = archivedLeads.filter((l) => leadIds.includes(l.id));
    setArchivedLeads((prev) => prev.filter((l) => !leadIds.includes(l.id)));
    setLeads((prev) => [...unarchivedItems.map(l => ({ ...l, is_archived: false })), ...prev]);
    
    // Leads restored — no toast

    return true;
  }, [archivedLeads]);

  // Mark a lead as interested (adds to Interested page while keeping in CRM)
  const markAsInterested = useCallback(async (leadId: string) => {
    const lead = leads.find((l) => l.id === leadId) || archivedLeads.find((l) => l.id === leadId);
    if (!lead) return false;
    if (isSales()) return !!(await salesUpdateLead(leadId, { is_potential_work: true }));

    /* ⛔ ONE WRITE FOR THE STAR (2026-10-01): lead_mark_interested, the same function the star buttons and a
       salesperson's "Interested" call — so History records "Starred" whichever control was used. */
    const r = await markLeadInterested(leadId, true);
    if (!r.ok) {
      toast({
        title: 'Error updating lead',
        description: r.error,
        variant: 'destructive',
      });
      return false;
    }

    // Update local state — preserve existing status
    const updateLeadFn = (l: OutreachLead): OutreachLead => 
      l.id === leadId ? { ...l, is_potential_work: true } : l;
    
    setLeads((prev) => prev.map(updateLeadFn));
    setArchivedLeads((prev) => prev.map(updateLeadFn));

    window.dispatchEvent(new CustomEvent('track-lead-added'));
    window.dispatchEvent(new CustomEvent('demo-checklist-track-pressed'));
    window.dispatchEvent(new CustomEvent('demo-checklist-status-change'));
    
    // Added to Track Leads — no toast. History: lead_mark_interested wrote the "Starred" row.

    return true;
  }, [leads, archivedLeads]);

  // Mark multiple leads as interested
  const markMultipleAsInterested = useCallback(async (leadIds: string[]) => {
    if (leadIds.length === 0) return false;
    if (isSales()) { for (const id of leadIds) await salesUpdateLead(id, { is_potential_work: true }); return true; }

    /* The same one write as a single star (lead_mark_interested, History per lead), ten at a time. */
    const done: string[] = [];
    let firstError: string | null = null;
    for (let i = 0; i < leadIds.length; i += 10) {
      const batch = leadIds.slice(i, i + 10);
      const results = await Promise.all(batch.map((id) => markLeadInterested(id, true)));
      results.forEach((r, j) => { if (r.ok) done.push(batch[j]); else firstError ??= r.error; });
    }
    if (firstError) {
      toast({
        title: done.length ? `${leadIds.length - done.length} not marked interested` : 'Error updating leads',
        description: firstError,
        variant: 'destructive',
      });
    }
    if (done.length === 0) return false;

    // Update local state — preserve existing status
    const updateLeadFn = (l: OutreachLead): OutreachLead =>
      done.includes(l.id) ? { ...l, is_potential_work: true } : l;
    
    setLeads((prev) => prev.map(updateLeadFn));
    setArchivedLeads((prev) => prev.map(updateLeadFn));

    window.dispatchEvent(new CustomEvent('track-lead-added'));
    window.dispatchEvent(new CustomEvent('demo-checklist-track-pressed'));
    
    // Added to Track Leads — no toast

    return true;
  }, []);

  // Search archived leads by phone number
  const searchArchivedByPhone = useCallback(async (phoneQuery: string): Promise<OutreachLead[]> => {
    if (!user || !phoneQuery.trim()) return [];

    // Strip non-digits for search
    const digitsOnly = phoneQuery.replace(/\D/g, '');
    if (digitsOnly.length < 3) return [];

    const { data, error } = await supabase
      .from('outreach_leads')
      .select('*')
      .eq('is_archived', true)
      .ilike('phone', `%${digitsOnly}%`);

    if (error) {
      console.error('Error searching archived leads:', error);
      return [];
    }

    return (data || []) as OutreachLead[];
  }, [user]);

   // Bulk lookup phone numbers — uses google-place-details with concurrency-3
   const bulkLookupPhones = useCallback(async (
     leadIds?: string[],
     onProgress?: (current: number, total: number) => void
   ): Promise<{ updated: number; skipped: number; failed: number; total: number }> => {
     if (isSales()) { refuseForSales('Looking up phone numbers'); return { updated: 0, skipped: 0, failed: 0, total: 0 }; }
     if (!user) return { updated: 0, skipped: 0, failed: 0, total: 0 };

     // Collect target leads
     const allTargetLeads = leadIds
       ? [...leads, ...archivedLeads].filter(l => leadIds.includes(l.id))
       : [...leads, ...archivedLeads];

     const eligible: typeof allTargetLeads = [];
     let skippedCount = 0;

     for (const lead of allTargetLeads) {
       if (lead.phone) {
         skippedCount++;
         continue;
       }
       const placeId = (lead as any).place_id;
       if (!placeId) {
         skippedCount++;
         console.log(`Skipped lead ${lead.id} (${lead.business_name}): no place_id`);
         continue;
       }
       eligible.push(lead);
     }

     const total = allTargetLeads.length;
     if (eligible.length === 0) {
       onProgress?.(total, total);
       return { updated: 0, skipped: skippedCount, failed: 0, total };
     }

     let updatedCount = 0;
     let failedCount = 0;
     let processed = skippedCount; // already-skipped leads count as processed for progress

     // Concurrency-3 pool
     const queue = [...eligible];
     const processOne = async () => {
       while (queue.length > 0) {
         const lead = queue.shift();
         if (!lead) break;
         const placeId = (lead as any).place_id;
         try {
           const { data: details, error: detailsError } = await supabase.functions.invoke('google-place-details', {
              body: { placeId, triggerSource: 'bulk_recover' },
           });

           if (detailsError || !details) {
             failedCount++;
             console.error(`Bulk enrich failed for ${lead.business_name}:`, detailsError);
           } else {
             /* Store whatever came back BEFORE judging the phone. This branch used to be
                `else if (details?.phone)`, so a business with no listed phone had its address, town,
                rating and review count discarded even though the call had already been paid for.
                A no-phone result is still "skipped" for the operator-facing counts — that is what the
                button promises to recover — but the data is kept. */
             const written = await applyPlaceDetailsToLead(lead.id, details as PlaceDetailsResponse);
             if (details.phone) {
               if (written) {
                 updatedCount++;
               } else {
                 failedCount++;
                 console.error(`DB update failed for ${lead.business_name}`);
               }
             } else {
               // No phone found — count as skipped, do NOT remove lead
               skippedCount++;
             }
           }
         } catch (e) {
           failedCount++;
           console.error(`Bulk enrich error for ${lead.business_name}:`, e);
         }
         processed++;
         onProgress?.(processed, total);
       }
     };

     // Start CONCURRENCY workers
     await Promise.all(Array.from({ length: CONCURRENCY }, () => processOne()));

     // Refresh state once at the end
     await fetchLeads();

     return { updated: updatedCount, skipped: skippedCount, failed: failedCount, total };
   }, [user, leads, archivedLeads, fetchLeads]);

  /* After a CSV import (2026-10-05, fix/csv-lead-import; docs/pre-sales-certification/csv-import-fix.md).
     ⛔ THE IMPORT ITSELF IS THE SERVER'S: CSVImportDialog sends the rows to import_leads, which validates them, finds
     duplicates with the canonical identity lookup, stamps the owner (always the person importing — a salesperson
     can never name anyone else) and writes. It used to be a browser loop here inserting list_type 'imported', which
     the database refuses, so every row failed while the dialog said "Successfully imported".
     This only refreshes the list and, for the ADMIN, verifies the towns of the leads just created. A salesperson's
     import is not town-checked: backfill-lead-towns pays per lead and reads only the caller's own data rows (a
     salesperson owns none), exactly as their "Add a lead" without a lookup today. */
  const afterCsvImport = useCallback(async (createdIds: string[]) => {
    const importedIds = createdIds;
    if (isSales() || !importedIds.length) {
      await fetchLeads();
      return { verified: 0, unverifiable: 0 };
    }

    /* ── VERIFY AS IT LANDS — Paul's Layer 1, 2026-08-14 ─────────────────────────────────────────
       Every imported row goes straight through backfill-lead-towns: the SAME resolveDerivedTown the
       add-lead path uses, plus the three-guard place-id resolution for rows a CSV cannot carry an
       id for. Rows Google confirms get derived_town (verified); rows it cannot confidently match
       are stamped settled-unverifiable, and every outreach/audit gate holds them from that moment.
       ⛔ CHUNKED at the function's own MAX_PER_CALL so a big CSV is verified in full rather than
       first-150-only — an unchecked tail would pass the gates by absence, which is the exact hole
       this closes. Failures here do NOT undo the import: the rows stay, unchecked, retryable from
       the backfill button, and the toast says so rather than pretending. */
    let verified = 0, unverifiable = 0, unresolvedNote = '';
    if (importedIds.length) {
      toast({ title: 'Verifying towns…', description: `Checking ${importedIds.length} imported lead${importedIds.length === 1 ? '' : 's'} against Google Places.` });
      const CHUNK = 150; // backfill-lead-towns' MAX_PER_CALL
      for (let i = 0; i < importedIds.length; i += CHUNK) {
        const { data, error: vErr } = await supabase.functions.invoke<{
          ok?: boolean; filled?: number; no_town?: number; failed?: number; capped?: number; error?: string;
        }>('backfill-lead-towns', { body: { lead_ids: importedIds.slice(i, i + CHUNK) } });
        if (vErr || data?.ok === false) {
          unresolvedNote = ` Verification stopped early (${vErr?.message ?? data?.error ?? 'unknown error'}) — the rest stay unchecked and can be verified from the backfill button.`;
          break;
        }
        verified += data?.filled ?? 0;
        unverifiable += data?.no_town ?? 0;
        if ((data?.capped ?? 0) > 0) {
          unresolvedNote = ' The daily verification budget ran out part-way — the rest stay unchecked; re-run the backfill button tomorrow.';
          break;
        }
      }
      toast({
        title: 'Import verified',
        description: `${verified} town${verified === 1 ? '' : 's'} confirmed by Google; ${unverifiable} unverifiable (flagged and excluded from outreach and audits).${unresolvedNote}`,
      });
    }

    await fetchLeads();

    return { verified, unverifiable };
  }, [fetchLeads, toast]);

  const updateClientDetails = useCallback(async (
    leadId: string,
    details: Partial<Pick<OutreachLead, 'amount_paid' | 'paid_for' | 'payment_date' | 'project_duration' | 'next_checkin_date' | 'checkin_notes'>>
  ) => {
    return updateLead(leadId, details);
  }, [updateLead]);

  return {
    leads,
    archivedLeads,
    activities,
    isLoading,
    addLead: addLeadSingleFlight,
    updateLead,
    assignCampaign,
    removeFromMyLeads,
    updateStatus,
    updateNextAction,
    updateNotes,
    updateBusinessName,
    updateClientDetails,
    deleteLead,
    removeFreshLead,
    deleteMultiple,
    resetMultiple,
    resetToFreshMultiple,
    deleteAllLeads,
    archiveLead,
    unarchiveLead,
    archiveMultiple,
    unarchiveMultiple,
    markAsInterested,
    markMultipleAsInterested,
    searchArchivedByPhone,
    fetchActivities,
    logActivity,
    isInOutreach,
    bulkLookupPhones,
    afterCsvImport,
    fetchLeads,
    refetch: fetchLeads,
    leadLoad,
    retryLeadLoad,
    phoneFetchStatus,
    retryPhoneFetch,
  };
}
